def largest_number(numbers):
    if not numbers:
        raise ValueError("numbers must not be empty")
    largest = numbers[0]
    for number in numbers[1:]:
        if number > largest:
            largest = number
    return largest

Use int() inside a try/except block to handle invalid input:
try:
    age = int(input("Enter age: "))
except ValueError:
    print("Please enter a valid integer.")

A unit test checks a small piece of code in isolation. For example:
import unittest

def add(a, b):
    return a + b

class AddTests(unittest.TestCase):
    def test_adds_two_numbers(self):
        self.assertEqual(add(2, 3), 5)

if __name__ == "__main__":
    unittest.main()
Run the test file with python test_file.py or discover tests using python -m unittest.
